#[test]
fn agent_inclusive_records_are_never_presented_as_model_only_comparisons() {
    let spec = spec(&["model-a", "model-b"], &[READ_TASK], 1);
    let mut results = every_run(&spec);
    let mut harness = BenchmarkHarnessIdentity::new("coding-agent-adapter", "harness-v1");
    harness.adapter_version = TelemetryValue::Measured("adapter-v1".to_owned());
    harness.mcp_tool_contract =
        TelemetryValue::Measured("editor-mcp-contract-v1".to_owned());
    harness.permission_profile =
        TelemetryValue::Measured("benchmark-agent-readwrite-v1".to_owned());
    let runtime = BenchmarkRuntimeIdentity::coding_agent(
        harness,
        BenchmarkAgentRuntimeIdentity {
            runtime_id: "goose".to_owned(),
            runtime_version: TelemetryValue::Measured("1.0".to_owned()),
        },
    );
    for result in &mut results {
        if let Some(record) = result.record.as_mut() {
            record.identity.runtime = Some(runtime.clone());
        }
    }
    let comparison = compare_experiment(&spec, &results).expect("compare");
    assert_eq!(
        comparison.equivalence,
        BenchmarkComparisonEquivalence::NonEquivalent {
            differences: vec!["coding_agent_comparison".to_owned()],
        }
    );
    assert!(!comparison.supports_recommendation());
}

